  ('dd35eec5-dbdc-5824-8479-c8fa631037f9', null, (select id from public.skills where slug = 'read-g11-main-idea-summary'), null, 'easy',
   $q$Which two reasons does the writer develop to support the central claim?$q$, $q$[{"text":"Bright lights cause traffic accidents, and dim lights help the town attract tourists.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"Warm bulbs last longer, and timers are easy for the town to install in parking lots.","is_correct":false,"misconception_token":"misreads-detail"},{"text":"Upward light wastes money, and unshielded light harms insects, birds and people's sleep.","is_correct":true},{"text":"Stars are beautiful, and the school field is the best place in town to see them.","is_correct":false,"misconception_token":"misreads-emphasis"}]$q$::jsonb, $q$Upward light wastes money, and unshielded light harms insects, birds and people's sleep.$q$, $q$Paragraph 3 begins "The first reason is simple waste," and paragraph 4 begins "The second reason is the effect on living things." The stars appear as framing in the opening and closing, not as one of the two stated reasons.$q$, 'draft', '0f82031e-88f1-5a7f-a969-d3e6f4fc3e6a')
