  ('81aeeab5-0223-594c-9351-93e07157386b', null, (select id from public.skills where slug = 'read-g11-main-idea-summary'), null, 'medium',
   $q$How does the fifth paragraph contribute to the development of the writer's argument?$q$, $q$[{"text":"It summarizes the energy report's findings about how much of the lighting budget is wasted each year.","is_correct":false,"misconception_token":"misreads-structure"},{"text":"It admits that the proposal will make Westmere less safe but argues that the stars are worth the risk.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"It adds a third reason for the standard: that dimmer streets will encourage people to stay home at night.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"It answers the safety objection by arguing that shielded lights help people see better than glaring ones.","is_correct":true}]$q$::jsonb, $q$It answers the safety objection by arguing that shielded lights help people see better than glaring ones.$q$, $q$Paragraph 5 names the worry about safety and replies that glare "makes it harder to see into shadows" while shielded lights spread even light. The writer never concedes that the town will be less safe.$q$, 'draft', '0f82031e-88f1-5a7f-a969-d3e6f4fc3e6a')
